<?php
require_once __DIR__ . '/../includes/layout.php';
$u = require_role('admin');
if (is_post()) { csrf_check(); $act = post('action'); $id = (int)post('id');
    if ($act === 'item') {
        if (!post('name')) flash('error', 'Item name is required.');
        else { $d = [post('name'), post('category'), post('sku'), (int)post('quantity'), (int)post('reorder_level'), (int)post('unit_cost'), (int)post('supplier_id') ?: null];
            if ($id) q('UPDATE inventory SET name=?,category=?,sku=?,quantity=?,reorder_level=?,unit_cost=?,supplier_id=? WHERE id=?', [...$d, $id]); else q('INSERT INTO inventory (name,category,sku,quantity,reorder_level,unit_cost,supplier_id) VALUES (?,?,?,?,?,?,?)', $d); flash('success', 'Inventory item saved.'); }
        redirect('admin/inventory.php');
    } elseif ($act === 'del_item') { q('DELETE FROM inventory WHERE id=?', [$id]); flash('success', 'Item deleted.'); redirect('admin/inventory.php'); }
    elseif ($act === 'supplier') {
        if (!post('name')) flash('error', 'Supplier name is required.');
        else { $d = [post('name'), post('phone'), post('email'), post('address')]; if ($id) q('UPDATE suppliers SET name=?,phone=?,email=?,address=? WHERE id=?', [...$d, $id]); else q('INSERT INTO suppliers (name,phone,email,address) VALUES (?,?,?,?)', $d); flash('success', 'Supplier saved.'); }
        redirect('admin/inventory.php?tab=sup');
    } elseif ($act === 'del_sup') { q('DELETE FROM suppliers WHERE id=?', [$id]); q('UPDATE inventory SET supplier_id=NULL WHERE supplier_id=?', [$id]); flash('success', 'Supplier deleted.'); redirect('admin/inventory.php?tab=sup'); }
    elseif ($act === 'auto_po') { $n = 0;
        foreach (rows('SELECT * FROM inventory WHERE quantity<=reorder_level') as $i) { if (val("SELECT 1 FROM purchase_orders WHERE item_id=? AND status='ordered'", [$i['id']])) continue; $qty = max($i['reorder_level'] * 2 - $i['quantity'], 1); q('INSERT INTO purchase_orders (item_id,supplier_id,qty,total_cost) VALUES (?,?,?,?)', [$i['id'], $i['supplier_id'], $qty, $qty * $i['unit_cost']]); $n++; }
        flash($n ? 'success' : 'warning', $n ? "$n purchase order(s) generated for low-stock items." : 'No new purchase orders needed.'); redirect('admin/inventory.php?tab=po');
    } elseif ($act === 'receive') { $po = row("SELECT * FROM purchase_orders WHERE id=? AND status='ordered'", [$id]); if ($po) { q('UPDATE inventory SET quantity=quantity+? WHERE id=?', [$po['qty'], $po['item_id']]); q("UPDATE purchase_orders SET status='received' WHERE id=?", [$id]); flash('success', 'Stock received and inventory updated.'); } redirect('admin/inventory.php?tab=po'); }
}
$items = rows('SELECT i.*, s.name AS supplier FROM inventory i LEFT JOIN suppliers s ON s.id=i.supplier_id ORDER BY (i.quantity<=i.reorder_level) DESC, i.name');
$sups = rows('SELECT * FROM suppliers ORDER BY name'); $pos = rows('SELECT po.*, i.name AS item, s.name AS supplier FROM purchase_orders po JOIN inventory i ON i.id=po.item_id LEFT JOIN suppliers s ON s.id=po.supplier_id ORDER BY po.id DESC');
$low = count(array_filter($items, fn($i) => $i['quantity'] <= $i['reorder_level'])); $tab = $_GET['tab'] ?? 'items';
panel_header('Inventory Management', $u);
?>
<div class="stats"><div class="stat"><div class="si"><?= icon('box', 26) ?></div><div><b><?= count($items) ?></b><span>Items</span></div></div><div class="stat red"><div class="si"><?= icon('alert', 26) ?></div><div><b><?= $low ?></b><span>Low Stock</span></div></div><div class="stat blue"><div class="si"><?= icon('users', 26) ?></div><div><b><?= count($sups) ?></b><span>Suppliers</span></div></div><div class="stat green"><div class="si"><?= icon('money', 26) ?></div><div><b><?= money(array_sum(array_map(fn($i) => $i['quantity'] * $i['unit_cost'], $items))) ?></b><span>Stock Value</span></div></div></div>
<div class="box"><div class="tabs"><button class="<?= $tab === 'items' ? 'on' : '' ?>" data-tab="t1">Stock Items</button><button class="<?= $tab === 'sup' ? 'on' : '' ?>" data-tab="t2">Suppliers</button><button class="<?= $tab === 'po' ? 'on' : '' ?>" data-tab="t3">Purchase Orders</button></div>
<div class="tab <?= $tab === 'items' ? 'on' : '' ?>" id="t1"><div class="toolbar"><input type="search" class="grow" placeholder="Search items…" data-search="#itTbl"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="auto_po"><button class="btn btn-ghost btn-sm"><?= icon('refresh', 15) ?> Auto Purchase Orders</button></form><button class="btn btn-gold btn-sm" data-open="itModal" data-reset><?= icon('plus', 16) ?> Add Item</button></div>
<div class="tbl-wrap"><table id="itTbl"><thead><tr><th>Item</th><th>Category</th><th>SKU</th><th>Qty</th><th>Reorder at</th><th>Unit Cost</th><th>Supplier</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($items as $i): $lowi = $i['quantity'] <= $i['reorder_level']; ?><tr><td><b><?= e($i['name']) ?></b></td><td><?= e($i['category']) ?></td><td><?= e($i['sku']) ?></td><td><b><?= $i['quantity'] ?></b></td><td><?= $i['reorder_level'] ?></td><td><?= money($i['unit_cost']) ?></td><td><?= e($i['supplier'] ?: '-') ?></td><td><?= $lowi ? '<span class="badge b-low">Low stock</span>' : '<span class="badge b-ok">In stock</span>' ?></td>
<td><div class="acts"><button class="btn btn-ghost btn-xs" data-open="itModal" data-json='<?= e(json_encode($i)) ?>'><?= icon('edit', 13) ?></button><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="del_item"><input type="hidden" name="id" value="<?= $i['id'] ?>"><button class="btn btn-red btn-xs" data-confirm="Delete item?"><?= icon('trash', 13) ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="tab <?= $tab === 'sup' ? 'on' : '' ?>" id="t2"><div class="toolbar"><div class="grow"></div><button class="btn btn-gold btn-sm" data-open="spModal" data-reset><?= icon('plus', 16) ?> Add Supplier</button></div>
<div class="tbl-wrap"><table><thead><tr><th>Supplier</th><th>Phone</th><th>Email</th><th>Address</th><th></th></tr></thead><tbody><?php foreach ($sups as $s): ?><tr><td><b><?= e($s['name']) ?></b></td><td><?= e($s['phone']) ?></td><td><?= e($s['email']) ?></td><td><?= e($s['address']) ?></td><td><div class="acts"><button class="btn btn-ghost btn-xs" data-open="spModal" data-json='<?= e(json_encode($s)) ?>'><?= icon('edit', 13) ?></button><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="del_sup"><input type="hidden" name="id" value="<?= $s['id'] ?>"><button class="btn btn-red btn-xs" data-confirm="Delete supplier?"><?= icon('trash', 13) ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="tab <?= $tab === 'po' ? 'on' : '' ?>" id="t3"><?php if (!$pos): ?><div class="empty"><?= icon('box', 40) ?><p>No purchase orders yet. Click "Auto Purchase Orders" on the Stock tab.</p></div><?php else: ?><div class="tbl-wrap"><table><thead><tr><th>#</th><th>Item</th><th>Supplier</th><th>Qty</th><th>Total Cost</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($pos as $p): ?><tr><td>PO-<?= 100 + $p['id'] ?></td><td><?= e($p['item']) ?></td><td><?= e($p['supplier'] ?: '-') ?></td><td><?= $p['qty'] ?></td><td><?= money($p['total_cost']) ?></td><td><?= fdate($p['created_at'], 'd M Y') ?></td><td><?= badge($p['status'] === 'ordered' ? 'pending' : 'completed') ?> <small><?= e($p['status']) ?></small></td><td><?php if ($p['status'] === 'ordered'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="receive"><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="btn btn-gold btn-xs">Mark Received</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
<?php modal_open('itModal', 'Inventory Item'); ?>
<form method="post" data-validate novalidate><?= csrf_field() ?><input type="hidden" name="action" value="item"><input type="hidden" name="id"><div class="fg"><label>Item Name *</label><input type="text" name="name" required></div>
 <div class="row2"><div class="fg"><label>Category</label><input type="text" name="category"></div><div class="fg"><label>SKU</label><input type="text" name="sku"></div></div>
 <div class="row3"><div class="fg"><label>Quantity</label><input type="number" name="quantity" min="0" value="0"></div><div class="fg"><label>Reorder Level</label><input type="number" name="reorder_level" min="0" value="5"></div><div class="fg"><label>Unit Cost</label><input type="number" name="unit_cost" min="0" value="0"></div></div>
 <div class="fg"><label>Supplier</label><select name="supplier_id"><option value="">None</option><?php foreach ($sups as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><button class="btn btn-gold btn-block">Save Item</button></form><?php modal_close();
modal_open('spModal', 'Supplier'); ?>
<form method="post" data-validate novalidate><?= csrf_field() ?><input type="hidden" name="action" value="supplier"><input type="hidden" name="id"><div class="fg"><label>Name *</label><input type="text" name="name" required></div><div class="row2"><div class="fg"><label>Phone</label><input type="tel" name="phone"></div><div class="fg"><label>Email</label><input type="email" name="email"></div></div><div class="fg"><label>Address</label><input type="text" name="address"></div><button class="btn btn-gold btn-block">Save Supplier</button></form><?php modal_close(); panel_footer();
